package com.example.praticum.data.importer;
import android.content.Context;import android.net.Uri;import com.example.praticum.data.database.*;import com.example.praticum.data.entity.*;import java.io.*;import java.text.*;import java.util.*;import java.util.Locale;import java.util.UUID;
public final class EnrollmentExcelImporter{
 public interface Progress{void update(int done,int total,String message);}public static final class Result{public int enrollments,created,reused,duplicates,errorCount;public final List<String> errors=new ArrayList<>();}
 private EnrollmentExcelImporter(){}
 public static Result importFile(Context c,Uri uri,Progress cb)throws Exception{AppDatabase db=DatabaseProvider.getDatabase(c);AcademicYear y=db.academicYearDao().getActive();if(y==null)throw new IllegalStateException("Aucune année universitaire active.");List<List<String>> rows;try(InputStream in=c.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Impossible d’ouvrir le fichier.");rows=XlsxTableReader.read(in);}if(rows.size()<2)throw new IOException("Le fichier ne contient aucune ligne.");
 Map<String,Integer> h=headers(rows.get(0));for(String k:new String[]{"nom","prenom","groupe","niveau","specialite"})if(!h.containsKey(k))throw new IOException("Colonne obligatoire manquante : "+k);
 List<StudentGroup> groups=db.studentGroupDao().getByAcademicYear(y.getId());List<Level> levels=db.levelDao().getAll();Result r=new Result();int total=rows.size()-1,done=0;
 for(int n=1;n<rows.size();n++){List<String> row=rows.get(n);if(!emptyRow(row)){int line=n+1;try{String last=get(row,h,"nom"),first=get(row,h,"prenom"),code=get(row,h,"groupe"),lvl=get(row,h,"niveau"),sp=get(row,h,"specialite");if(last.isEmpty()||first.isEmpty()||code.isEmpty()||lvl.isEmpty()||sp.isEmpty())throw new IllegalArgumentException("Nom, prénom, groupe, niveau et spécialité sont requis.");StudentGroup g=findGroup(groups,levels,code,lvl,sp);if(g==null)throw new IllegalArgumentException("Aucun groupe correspondant dans l’année active "+y.getLabel()+".");
 String mat=nullIfEmpty(get(row,h,"matricule")),email=nullIfEmpty(get(row,h,"email")),stat=status(get(row,h,"statut"));final boolean[] made={false},dup={false};db.runInTransaction(()->{Student st=mat==null?null:db.studentDao().getByMatricule(mat);if(st==null&&email!=null)st=db.studentDao().getByEmail(email);if(st==null){st=new Student(last,first);st.setLastNameArabic(nullIfEmpty(get(row,h,"nomarabe")));st.setFirstNameArabic(nullIfEmpty(get(row,h,"prenomarabe")));st.setMatricule(mat);st.setEmail(email);st.setNotes(nullIfEmpty(get(row,h,"remarques")));db.studentDao().insert(st);made[0]=true;}if(db.enrollmentDao().getByStudentAndYear(st.getStudentId(),y.getId())!=null){dup[0]=true;return;}String name=g.getSubject().trim();Specialization specRow=db.specializationDao().getByName(name);if(specRow==null){specRow=new Specialization("SPEC-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT),name,null);specRow.setId((int)db.specializationDao().insert(specRow));}String date=new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date());db.enrollmentDao().insertAssigningGroupOrder(new Enrollment(st.getStudentId(),y.getId(),specRow.getId(),g.getLevelId(),g.getId(),0,stat,date));});
 if(dup[0])r.duplicates++;else{r.enrollments++;if(made[0])r.created++;else r.reused++;}
 }catch(Exception e){r.errorCount++;if(r.errors.size()<25)r.errors.add("Ligne "+line+" : "+(e.getMessage()==null?"erreur inconnue":e.getMessage()));}}
 done++;if(cb!=null)cb.update(done,total,"Importation : ligne "+(n+1)+" sur "+rows.size());}return r;}
 private static StudentGroup findGroup(List<StudentGroup>gs,List<Level>ls,String code,String level,String specialty){for(StudentGroup g:gs)if(eq(g.getCode(),code)&&eq(g.getSubject(),specialty)&&g.getLevelId()!=null)for(Level l:ls)if(l.getId()==g.getLevelId()&&(eq(l.getCode(),level)||eq(l.getName(),level)))return g;return null;}
 private static Map<String,Integer> headers(List<String> row){Map<String,Integer>m=new HashMap<>();for(int i=0;i<row.size();i++){String k=norm(row.get(i));switch(k){case"nom":m.put("nom",i);break;case"prenom":m.put("prenom",i);break;case"nomarabe":m.put("nomarabe",i);break;case"prenomarabe":m.put("prenomarabe",i);break;case"matricule":m.put("matricule",i);break;case"email":case"adresseelectronique":m.put("email",i);break;case"notes":case"remarques":m.put("remarques",i);break;case"codegroupe":m.put("groupe",i);break;case"niveau":m.put("niveau",i);break;case"specialite":case"formation":m.put("specialite",i);break;case"statut":case"statutinscription":m.put("statut",i);break;}}return m;}
 private static String get(List<String>r,Map<String,Integer>h,String k){Integer i=h.get(k);return i==null||i>=r.size()||r.get(i)==null?"":r.get(i).trim();}
 private static boolean emptyRow(List<String>r){for(String s:r)if(s!=null&&!s.trim().isEmpty())return false;return true;}
 private static String status(String s){switch(norm(s)){case"":case"encours":return Enrollment.STATUS_IN_PROGRESS;case"validee":case"valide":return Enrollment.STATUS_VALIDATED;case"redoublement":return Enrollment.STATUS_REPEAT;case"abandonnee":case"abandon":return Enrollment.STATUS_WITHDRAWN;default:throw new IllegalArgumentException("Statut invalide : utilisez En cours, Validée, Redoublement ou Abandonnée.");}}
 private static String norm(String s){return s==null?"":Normalizer.normalize(s.trim().toLowerCase(Locale.ROOT),Normalizer.Form.NFD).replaceAll("\\p{M}+","").replaceAll("[^a-z0-9]","");}
 private static boolean eq(String a,String b){return norm(a).equals(norm(b));}private static String nullIfEmpty(String s){return s==null||s.trim().isEmpty()?null:s.trim();}
}